t.script:
document.addEventListener('DOMContentLoaded', function () {
    var btn = document.getElementById('fs-stations-toggle');
    var body = document.getElementById('fs-stations-expand');
    if (btn && body) {
        btn.addEventListener('click', function () {
            var open = body.classList.toggle('show');
            btn.setAttribute('aria-expanded', open ? 'true' : 'false');
        });
    }
    var qs = document.querySelectorAll('[data-fs-faq]');
    qs.forEach(function (q) {
        q.addEventListener('click', function () {
            var id = q.getAttribute('data-fs-faq');
            var panel = document.querySelector('[data-fs-faq-panel="' + id + '"]');
            if (!panel) return;
            var open = panel.classList.contains('d-none');
            // close others
            document.querySelectorAll('[data-fs-faq-panel]').forEach(function (p) {
                p.classList.add('d-none');
            });
            document.querySelectorAll('[data-fs-faq]').forEach(function (b) {
                b.setAttribute('aria-expanded', 'false');
            });
            if (open) {
                panel.classList.remove('d-none');
                q.setAttribute('aria-expanded', 'true');
            }
        });
    });
});

document.addEventListener('DOMContentLoaded', function () {
    var loc = document.getElementById('location');
    var customWrap = document.getElementById('location_custom_wrap');
    var mapWrap = document.getElementById('pick_map_wrap');
    var surface = document.getElementById('surface_type');
    var surfaceOther = document.getElementById('surface_other_wrap');
    var modeCity = document.getElementById('loc_mode_city');
    var modeMap = document.getElementById('loc_mode_map');
    var cityWrap = document.getElementById('location_city_wrap');
    var coordsLbl = document.getElementById('fs-pick-coords');
    function setMapMode(on) {
        if (modeMap) modeMap.checked = !!on;
        if (modeCity) modeCity.checked = !on;
        if (loc && on) loc.value = 'outro';
        if (customWrap) customWrap.classList.toggle('d-none', !on);
        if (mapWrap) mapWrap.classList.toggle('d-none', !on);
        if (on) initPickMap();
    }
    function toggleLoc() {
        var isOther = (modeMap && modeMap.checked) || (loc && loc.value === 'outro');
        setMapMode(isOther);
    }
    if (modeCity) modeCity.addEventListener('change', function () { if (modeCity.checked) setMapMode(false); });
    if (modeMap) modeMap.addEventListener('change', function () { if (modeMap.checked) setMapMode(true); });
    function toggleSurface() {
        var isOther = surface && surface.value === 'other';
        if (surfaceOther) surfaceOther.classList.toggle('d-none', !isOther);
    }
    if (loc) loc.addEventListener('change', toggleLoc);
    if (surface) surface.addEventListener('change', toggleSurface);
    toggleLoc(); toggleSurface();

    var pickMapInited = false;
    function initPickMap() {
        if (pickMapInited || typeof L === 'undefined') return;
        var el = document.getElementById('fs-pick-map');
        if (!el) return;
        pickMapInited = true;
        var map = L.map('fs-pick-map').setView([39.5, -8.0], 6);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            maxZoom: 18,
            attribution: '&copy; OpenStreetMap'
        }).addTo(map);
        var marker = null;
        var latEl = document.getElementById('location_lat');
        var lngEl = document.getElementById('location_lng');
        if (latEl && lngEl && latEl.value && lngEl.value) {
            var lat0 = parseFloat(latEl.value), lng0 = parseFloat(lngEl.value);
            if (isFinite(lat0) && isFinite(lng0)) {
                marker = L.marker([lat0, lng0]).addTo(map);
                map.setView([lat0, lng0], 12);
            }
        }
        map.on('click', function (e) {
            if (marker) map.removeLayer(marker);
            marker = L.marker(e.latlng).addTo(map);
            if (latEl) latEl.value = e.latlng.lat.toFixed(5);
            if (lngEl) lngEl.value = e.latlng.lng.toFixed(5);
            if (coordsLbl) coordsLbl.textContent = 'Coordenadas: ' + e.latlng.lat.toFixed(5) + ', ' + e.latlng.lng.toFixed(5);
            if (loc) loc.value = 'outro';
            if (modeMap) modeMap.checked = true;
            var err = document.getElementById('fs-pick-error');
            if (err) err.classList.add('d-none');
        });
        setTimeout(function(){ map.invalidateSize(); }, 200);
    }

    var step1 = document.getElementById('fs-step1-form');
    if (step1) {
        step1.addEventListener('submit', function (ev) {
            var mapOn = modeMap && modeMap.checked;
            var latEl = document.getElementById('location_lat');
            var lngEl = document.getElementById('location_lng');
            var err = document.getElementById('fs-pick-error');
            if (mapOn) {
                var lat = latEl && latEl.value, lng = lngEl && lngEl.value;
                if (!lat || !lng || !isFinite(parseFloat(lat)) || !isFinite(parseFloat(lng))) {
                    ev.preventDefault();
                    if (err) err.classList.remove('d-none');
                    initPickMap();
                    return false;
                }
            }
        });
    }
    var step3 = document.getElementById('fs-step3-form');
    if (step3) {
        step3.addEventListener('submit', function (ev) {
            var input = document.getElementById('step3_bills');
            var err = document.getElementById('fs-bills-error');
            if (!input || !input.files || !input.files.length) return;
            var maxBytes = 5 * 1024 * 1024;
            var maxFiles = 5;
            var okTypes = {
                'application/pdf':1,'image/jpeg':1,'image/png':1,'image/webp':1,'' :1
            };
            if (input.files.length > maxFiles) {
                ev.preventDefault();
                if (err) { err.textContent = 'Máximo de 5 ficheiros.'; err.classList.remove('d-none'); }
                return false;
            }
            for (var i = 0; i < input.files.length; i++) {
                var f = input.files[i];
                if (f.size > maxBytes) {
                    ev.preventDefault();
                    if (err) { err.textContent = 'Ficheiro demasiado grande (máx. 5 MB): ' + f.name; err.classList.remove('d-none'); }
                    return false;
                }
            }
        });
    }
});

document.addEventListener('DOMContentLoaded', function () {
    var orgType = document.getElementById('step2_org_type');
    var npo = document.getElementById('step2_npo_confirm');
    var npoWrap = document.getElementById('step2_npo_wrap');
    var smeHint = document.getElementById('step2_sme_hint');
    var ngoTypes = {ong:1, ipss:1, fundacao:1, cooperativa:1};
    function syncEligibility() {
        if (!orgType) return;
        var isNgo = !!ngoTypes[orgType.value];
        if (npoWrap) npoWrap.classList.toggle('d-none', !isNgo);
        if (smeHint) smeHint.classList.toggle('d-none', isNgo);
        if (npo) {
            npo.required = isNgo;
            if (!isNgo) npo.checked = false;
        }
    }
    if (orgType) {
        orgType.addEventListener('change', syncEligibility);
        syncEligibility();
    }
});
